<!doctype html><html lang="zh-CN"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1.0"><title>通知设置</title><link rel="stylesheet" href="/assets/css/style.css"><style>.ns-page{padding:18px 16px 110px;background:var(--bg-main,#f6f8fb)}.ns-card{max-width:720px;margin:0 auto;background:var(--card-bg,#fff);border:1px solid var(--line-soft,#e2e8f0);border-radius:22px;padding:20px;box-shadow:0 10px 28px rgba(15,23,42,.045)}.ns-row{display:flex;justify-content:space-between;gap:14px;align-items:center;padding:14px 0;border-bottom:1px solid var(--line-soft,#e2e8f0)}.ns-row:last-child{border-bottom:0}.ns-title{font-weight:950;color:var(--text-main,#0f172a)}.ns-desc{font-size:12px;color:var(--text-soft,#64748b);margin-top:4px}.ns-row input{width:20px;height:20px}</style></head><body><?php require __DIR__ . '/../layouts/topbar.php'; ?><main class="ns-page"><form class="ns-card" method="post" action="/index.php?path=notification-settings"><?= csrf_field() ?><h1 style="margin:0 0 12px;">通知设置</h1><?php $items=['follow_post'=>['关注发帖通知','关注的人发布新帖时提醒'], 'reply'=>['被回复通知','别人回复你或你的回复时提醒'], 'mention'=>['被提及通知','别人 @ 你时提醒'], 'fans'=>['新粉丝通知','有人关注你时提醒'], 'like'=>['点赞通知','别人点赞你的帖子或回复时提醒'], 'favorite'=>['收藏通知','别人收藏你的帖子时提醒'], 'private_chat'=>['私聊通知','收到新的私聊时提醒'], 'review'=>['审核通知','内容审核通过、驳回或退回时提醒']]; foreach($items as $key=>$item): ?><label class="ns-row"><span><span class="ns-title"><?= $item[0] ?></span><span class="ns-desc"><?= $item[1] ?></span></span><input type="checkbox" name="<?= $key ?>" value="1" <?= !empty($settings[$key]) || ($key==='review' && !empty($settings['review_notice'])) ? 'checked' : '' ?>></label><?php endforeach; ?><div class="ns-row"><span><span class="ns-title">财务与系统通知</span><span class="ns-desc">为了安全和重要公告，这两类通知不可关闭。</span></span><span style="color:#94a3b8;font-size:13px;">始终开启</span></div><button class="btn" style="margin-top:16px;">保存设置</button></form></main><?php require __DIR__ . '/../../layouts/theme-toggle.php'; ?><?php require __DIR__ . '/../layouts/bottom-nav.php'; ?></body></html>
